async function f(n: number): Promise<number> { return Promise.resolve(n + 1); }
async function g(n: number): Promise<number> { const p = Promise.resolve(n * 2); return p; }
async function h(n: number): Promise<number> { await Promise.resolve(0); return Promise.resolve(n + 3); }
async function main(): Promise<void> {
  console.log(await f(1), await g(2), await h(3));
}
